-- hand-written: AI-006, at most one PENDING suggestion per product and warehouse.
-- The service expires older PENDING rows first; this index makes a race impossible.
CREATE UNIQUE INDEX "AiSuggestion_one_pending_per_product_warehouse"
  ON "AiSuggestion" ("productId", "warehouseId")
  WHERE "status" = 'PENDING';

-- hand-written: defence in depth, in the same spirit as the Inventory CHECK constraints.
ALTER TABLE "InventoryTransaction"
  ADD CONSTRAINT "InventoryTransaction_reservedAfter_non_negative" CHECK ("reservedAfter" IS NULL OR "reservedAfter" >= 0);

ALTER TABLE "AiSuggestion"
  ADD CONSTRAINT "AiSuggestion_suggestedQty_positive" CHECK ("suggestedQty" > 0),
  ADD CONSTRAINT "AiSuggestion_minimumOrderQty_positive" CHECK ("minimumOrderQty" >= 1),
  ADD CONSTRAINT "AiSuggestion_available_non_negative" CHECK ("available" >= 0),
  ADD CONSTRAINT "AiSuggestion_onOrder_non_negative" CHECK ("onOrder" >= 0),
  ADD CONSTRAINT "AiSuggestion_leadTimeDays_non_negative" CHECK ("leadTimeDays" >= 0),
  ADD CONSTRAINT "AiSuggestion_approved_has_requisition" CHECK ("status" <> 'APPROVED' OR "requisitionId" IS NOT NULL);
